const db = vpc.add(RDSPostgresqlInstance("Catalog"));
const cache = vpc.add(ElasticacheForRedis("Cache"));
const ecs = vpc.cluster("ECS cluster");
const worker = ecs.add(Fargate("Worker"));

const table = diagram.add(Dynamodb("Orders"));
const indexer = diagram.add(Lambda("search index"));
const bucket = diagram.add(S3("Invoices"));
const queue = diagram.add(SQS("InvoiceJobs"));
const dlq = diagram.add(SQS("InvoiceJobsDlq"));
const bus = diagram.add(Eventbridge("Events"));
const notify = diagram.add(Lambda("notify email"));
