const cron = diagram.add(EventbridgeScheduler("cron(0 2 * * ? *)"));

users.to([web, api]);
web.to(api);
web.to(bucket);
api.to(Edge({ label: "/orders" }), orders);
api.to(Edge({ label: "/webhooks/stripe" }), stripeWebhook);
stripe.to(Edge({ style: "dashed" }), api);
orders.to([table, db, cache, queue, bus]);
queue.to(Edge({ style: "dashed" }), dlq);
